UPDATE punch_photo_cleanup_jobs SET lease_until = #{leaseUntil}
WHERE path = #{path} AND next_attempt_at <= #{now}
  AND (lease_until IS NULL OR lease_until <= #{now})

UPDATE punch_photo_cleanup_jobs SET attempts = attempts + 1,
  next_attempt_at = #{nextAttemptAt}, lease_until = NULL
WHERE path = #{path} AND lease_until = #{leaseUntil}
